import React from 'react';

const Projects = () => {
  const projects = [
    { name: "LifeHub - IOS application", link: "https://github.com/keyul-coder/LifeHub", description: "A daily-use iOS app that helps users manage tasks, receive water reminders, view updated news, manage expenses, and get motivational quotes. Built using Swift and integrated with Firebase for real-time notifications and cloud data storage." },
    { name: "Wordle Clone", link: "#", description: "iOS game built using Swift and UIKit." },
    { name: "Todo App", link: "#", description: "React Native Todo app with modal and tab navigation." }
  ];

  return (
    <section id="projects" style={{ padding: '50px 20px', maxWidth: '900px', margin: 'auto' }}>
      <h2>Projects</h2>
      {projects.map(project => (
        <div key={project.name} style={{ marginBottom: '20px' }}>
          <h3>{project.name}</h3>
          <p>{project.description}</p>
          <a href={project.link} target="_blank" rel="noopener noreferrer">View Project</a>
        </div>
      ))}
    </section>
  );
};

export default Projects;
